select

from moneykeeper as mk
left join categories as c on mk.category_id = c.id
where mk.deleted_at = 0

    and mk.user_id = #{userId}


    and mk.transaction_date >= #{startDate}


    and mk.transaction_date <= #{endDate}

order by mk.updated_at desc

select

from moneykeeper as mk
left join categories as c on mk.category_id = c.id
where mk.deleted_at = 0
  and mk.ledger_id = #{ledgerId}

    and mk.user_id = #{userId}


    and mk.transaction_date >= #{startDate}


    and mk.transaction_date <= #{endDate}

order by mk.updated_at desc

select

from moneykeeper as mk
left join categories as c on mk.category_id = c.id
where mk.deleted_at = 0

    and mk.user_id = #{userId}


    and c.name = #{categoryName}


    and mk.transaction_date >= #{startDate}


    and mk.transaction_date <= #{endDate}

order by mk.updated_at desc

SELECT COALESCE(SUM(CASE WHEN type = 'income' THEN amount ELSE 0 END), 0) as totalIncome, COALESCE(SUM(CASE WHEN type = 'expense' THEN amount ELSE 0 END), 0) as totalExpense, COALESCE(SUM(CASE WHEN type = 'income' THEN amount ELSE -amount END), 0) as balance FROM moneykeeper mk WHERE user_id = #{userId} and mk.deleted_at = 0
AND transaction_date >= #{startDate}
AND transaction_date <= #{endDate}

SELECT * FROM moneykeeper
WHERE user_id = #{userId} and deleted_at = 0

    AND transaction_date >= #{startDate}


    AND transaction_date <= #{endDate}

ORDER BY transaction_date DESC
